protected void cleanup()
{
    SysOutgoingEmailTable            sysOutgoingEmailTable;
    TransDateTime                    delDate = cleanupTaskSettings.getCleanupDateTime();

    while select sysOutgoingEmailTable
        where sysOutgoingEmailTable.CreatedDateTime &&
              sysOutgoingEmailTable.CreatedDateTime <= delDate
    {
        if (!this.deleteRecord(sysOutgoingEmailTable))
        {
            break;
        }
    }
}

public void estimate()
{
    SysOutgoingEmailTable            sysOutgoingEmailTable;
    TransDateTime                    delDate = cleanupTaskSettings.getCleanupDateTime();

    select count(RecId) from sysOutgoingEmailTable
        where sysOutgoingEmailTable.CreatedDateTime &&
              sysOutgoingEmailTable.CreatedDateTime <= delDate;

    info(strFmt("SysOutgoingEmailTable count for %1 date: %2", delDate, sysOutgoingEmailTable.RecId));
}
